234	/** 交易后动态调价：买入涨价，卖出降价 */
235	function adjustPriceAfterTrade(locKey, goodId, delta) {
236	  const state = StateManager.getState();
237	  const good = getGoodById(goodId);
238	  if (!good) return;
239	  const prices = state.trade.goodsPrices[locKey];
240	  if (!prices) return;
241	  const oldPrice = prices[goodId] || good.basePrice;
242	  const change = oldPrice * delta;
243	  let newPrice = oldPrice + change;
244	  // 限制范围
245	  newPrice = Math.max(
246	    good.basePrice * 0.3,
247	    Math.min(good.basePrice * 5, newPrice),
248	  );
249	  newPrice = Math.round(newPrice * 100) / 100;
250	  prices[goodId] = newPrice;
251	}
