253	/** 获取当前地点某商品的零售价 */
254	function getCurrentPrice(locKey, goodId) {
255	  const state = StateManager.getState();
256	  const prices = state.trade.goodsPrices[locKey];
257	  if (prices && prices[goodId] !== undefined) {
258	    return prices[goodId];
259	  }
260	  const good = getGoodById(goodId);
261	  return good ? good.basePrice : 1;
262	}
263	
264	/** 获取某商品在所有地点的最低价格（用于价格对比） */
265	function getLowestPrice(goodId) {
266	  const state = StateManager.getState();
267	  let lowest = Infinity;
268	  let lowestLoc = null;
269	  for (const locKey of Object.keys(LOCATIONS)) {
270	    const prices = state.trade.goodsPrices[locKey] || {};
271	    const price = prices[goodId];
272	    if (price && price < lowest) {
273	      lowest = price;
274	      lowestLoc = locKey;
275	    }
276	  }
277	  return { price: lowest, location: lowestLoc };
278	}
279	
280	/** 获取某商品在所有地点的最高价格 */
281	function getHighestPrice(goodId) {
282	  const state = StateManager.getState();
283	  let highest = 0;
284	  let highestLoc = null;
285	  for (const locKey of Object.keys(LOCATIONS)) {
286	    const prices = state.trade.goodsPrices[locKey] || {};
287	    const price = prices[goodId];
288	    if (price && price > highest) {
289	      highest = price;
290	      highestLoc = locKey;
291	    }
292	  }
293	  return { price: highest, location: highestLoc };
294	}
295	
296	/** 估算平均买入价 */
297	function getAvgBuyPrice(state, goodId) {
298	  const item = state.inventory.items.find((i) => i.id === goodId);
299	  return item ? item.avgBuyPrice || 0 : 0;
300	}
301	
302	/** 更新所有地点所有商品的价格（每3天调用一次） */
303	function updateAllPrices(state) {
304	  for (const locKey of Object.keys(LOCATIONS)) {
305	    const loc = LOCATIONS[locKey];
306	    // 确保价格对象存在
307	    if (!state.trade.goodsPrices[locKey]) {
308	      state.trade.goodsPrices[locKey] = {};
309	    }
310	    for (const good of GOODS) {
311	      let price = good.basePrice;
312	
313	      // 1. 地点倍率
314	      if (loc.priceMod && loc.priceMod[good.id]) {
315	        price *= loc.priceMod[good.id];
316	      }
317	
318	      // 2. 随机波动 ±25%
319	      const fluctuation = 0.75 + Math.random() * 0.5;
320	      price *= fluctuation;
321	
322	      // 3. 均值回归（10%向旧价格靠拢）
323	      const oldPrice = state.trade.goodsPrices[locKey][good.id] || price;
324	      price = price + (oldPrice - price) * 0.1;
325	
326	      // 4. 限制在合理范围
327	      price = Math.max(
328	        good.basePrice * 0.25,
329	        Math.min(good.basePrice * 6, price),
330	      );
331	      price = Math.round(price * 100) / 100;
332	
333	      state.trade.goodsPrices[locKey][good.id] = price;
334	    }
335	  }
336	  state.trade.lastPriceUpdate = state.player.day;
337	}
