551	    var curPrice = null;
552	    if (priceData && priceData.length === 1) curPrice = priceData[0].price;
553	    if (curPrice !== null) {
554	      ctx.fillStyle = color || "#4fc3f7";
555	      ctx.font = "bold 11px sans-serif";
556	      ctx.fillText("¥" + curPrice.toFixed(2), W / 2, H / 2 + 18);
557	    }
558	    return;
559	  }
560	
561	  var prices = [];
562	  for (var i = 0; i < data.length; i++) prices.push(data[i].price);
563	
564	  var minP = prices[0],
565	    maxP = prices[0];
566	  for (var i = 1; i < prices.length; i++) {
567	    if (prices[i] < minP) minP = prices[i];
568	    if (prices[i] > maxP) maxP = prices[i];
569	  }
570	  var range = maxP - minP;
571	  if (range === 0) range = minP * 0.1 || 1;
572	  var padT = 4,
573	    padB = 4,
574	    padL = 4,
575	    padR = 4;
576	  var chartW = W - padL - padR;
577	  var chartH = H - padT - padB;
578	
579	  // 网格线
580	  if (ctx.strokeStyle) {
581	    ctx.strokeStyle = "rgba(255,255,255,0.06)";
582	    ctx.lineWidth = 0.5;
583	    for (var i = 0; i < 4; i++) {
584	      var y = padT + (chartH / 4) * i;
585	      ctx.beginPath();
586	      ctx.moveTo(padL, y);
587	      ctx.lineTo(W - padR, y);
588	      ctx.stroke();
589	    }
590	  }
591	
592	  // 折线
593	  var lineColor = color || "#4fc3f7";
594	  ctx.beginPath();
595	  ctx.strokeStyle = lineColor;
596	  ctx.lineWidth = 1.5;
597	  var firstX, firstY, lastX, lastY;
598	  for (var i = 0; i < prices.length; i++) {
599	    var x = padL + (i / (prices.length - 1)) * chartW;
600	    var y = padT + chartH - ((prices[i] - minP) / range) * chartH;
601	    if (i === 0) {
602	      ctx.moveTo(x, y);
603	      firstX = x;
604	      firstY = y;
605	    } else {
606	      ctx.lineTo(x, y);
607	    }
608	    if (i === prices.length - 1) {
609	      lastX = x;
610	      lastY = y;
611	    }
612	  }
613	  ctx.stroke();
614	
615	  // 渐变填充
616	  var grad = ctx.createLinearGradient(0, padT, 0, H - padB);
617	  grad.addColorStop(0, lineColor + "30");
618	  grad.addColorStop(1, lineColor + "02");
619	  ctx.fillStyle = grad;
620	  ctx.beginPath();
621	  ctx.moveTo(firstX, H - padB);
622	  for (var i = 0; i < prices.length; i++) {
623	    var x = padL + (i / (prices.length - 1)) * chartW;
624	    var y = padT + chartH - ((prices[i] - minP) / range) * chartH;
625	    if (i === 0) ctx.lineTo(x, y);
626	    else ctx.lineTo(x, y);
627	  }
628	  ctx.lineTo(lastX, H - padB);
629	  ctx.closePath();
630	  ctx.fill();
631	
632	  // 当前价格
633	  var lastPrice = prices[prices.length - 1];
634	  var prevPrice = prices.length >= 2 ? prices[prices.length - 2] : lastPrice;
635	  var chg = lastPrice - prevPrice;
636	  var chgPct = prevPrice !== 0 ? ((chg / prevPrice) * 100).toFixed(2) : "0.00";
637	  var chgText = (chg >= 0 ? "+" : "") + chgPct + "%";
638	
639	  ctx.fillStyle = lineColor;
640	  ctx.font = "bold 11px sans-serif";
641	  ctx.textAlign = "left";
642	  ctx.fillText(lastPrice.toFixed(2), padL + 2, padT + 10);
643	
644	  ctx.fillStyle = chg >= 0 ? "#4caf50" : "#f44336";
645	  ctx.font = "9px sans-serif";
646	  ctx.fillText(chgText, padL + 2, padT + 21);
647	}
