  },
];

const CAR_TYPES = [
  {
    id: "van",
    name: "二手面包车",
    price: 30000,
    depreciation: 0.0008,
    maintenance: 300,
    travelBonus: 5,
    desc: "实用之选",
  },
  {
    id: "sedan",
