    var sym = items[i];
    var s = null;
    for (var j = 0; j < INV_STOCKS.length; j++) {
      if (INV_STOCKS[j].symbol === sym) {
        s = INV_STOCKS[j];
        break;
      }
    }
    if (!s) continue;
    var m = inv.stockMarket[sym];
    if (!m) continue;
    var h = null;
    for (var j = 0; j < inv.stockHoldings.length; j++) {
      if (inv.stockHoldings[j].symbol === sym) {
        h = inv.stockHoldings[j];
        break;
      }
    }
    var chg =
      m.history.length >= 2
        ? m.price - m.history[m.history.length - 2].price
        : 0;
    var clr = chg >= 0 ? "var(--success)" : "var(--danger)";
    var unit = s.unit || "份";
    var cid = "chart-" + sym;

    var card = document.createElement("div");
    card.className = "action-card";
    card.style.borderLeft = "3px solid " + clr;
    card.innerHTML =
      '<div style="display:flex;justify-content:space-between;">' +
      "<strong>" +
      s.name +
      " (" +
      sym +
      ")</strong>" +
      '<span style="color:' +
      clr +
      '">' +
      m.price.toFixed(2) +
      "</span>" +
      "</div>" +
      '<div style="font-size:10px;color:var(--text-muted);">' +
      s.desc +
      "</div>" +
      (h
        ? '<div style="font-size:10px;margin:4px 0;">' +
          "持有 " +
          h.shares +
          " " +
          unit +
          " 均价" +
          h.avgPrice.toFixed(2) +
          ' 盈亏<span style="color:' +
          clr +
          '">' +
          Math.round((m.price - h.avgPrice) * h.shares) +
          "</span>" +
          "</div>"
        : "") +
      '<div style="display:flex;gap:3px;margin-top:4px;">' +
      '<button class="btn btn-sm btn-success ibuy" data-s="' +
      sym +
      '" data-q="1">买1' +
      unit +
      "</button>" +
      '<button class="btn btn-sm btn-success ibuy" data-s="' +
      sym +
      '" data-q="10">买10' +
      unit +
      "</button>" +
      '<button class="btn btn-sm btn-danger isell" data-s="' +
      sym +
      '" data-q="1">卖1' +
      unit +
      "</button>" +
      '<button class="btn btn-sm btn-danger isell" data-s="' +
      sym +
      '" data-q="' +
      (h ? h.shares : 0) +
      '">全卖</button>' +
      "</div>" +
      '<canvas id="' +
      cid +
      '" width="200" height="60" style="width:200px;height:60px;margin-top:4px;background:rgba(0,0,0,0.15);border-radius:3px;"></canvas>';
    grid.appendChild(card);
  }

  area.appendChild(grid);

  setTimeout(function () {
    for (var i = 0; i < items.length; i++) {
      var m = inv.stockMarket[items[i]];
      if (m) drawPriceChart("chart-" + items[i], m.history, "#81c784");
    }
    area.querySelectorAll(".ibuy").forEach(function (b) {
      b.onclick = function () {
        buyInvStock(this.dataset.s, parseInt(this.dataset.q));
        renderInvestmentTab(state, parent);
      };
    });
    area.querySelectorAll(".isell").forEach(function (b) {
      b.onclick = function () {
        sellInvStock(this.dataset.s, parseInt(this.dataset.q));
        renderInvestmentTab(state, parent);
      };
    });
  }, 0);
}

// ---- 子tab渲染：房产 ----
function renderProperties(area, inv) {
  var list = inv.properties || [];
  if (list.length === 0) {
    area.innerHTML =
      '<p style="color:var(--text-muted);font-size:12px;">尚未购入房产，前往商城购买。</p>';
    return;
  }

  var div = document.createElement("div");
  div.className = "action-cards";

  for (var i = 0; i < list.length; i++) {
    var p = list[i];
    var cur = p.currentPrice || p.buyPrice;
    var buyP = p.buyPrice;
    var diff = cur - buyP;
    var pct = ((diff / buyP) * 100).toFixed(1);
    var clr = diff >= 0 ? "var(--success)" : "var(--danger)";

    var card = document.createElement("div");
    card.className = "action-card";
    card.style.borderLeft = "3px solid " + clr;
    card.innerHTML =
      '<div style="display:flex;justify-content:space-between;">' +
      "<strong>" +
      p.name +
      "</strong>" +
      '<span style="color:' +
      clr +
      '">' +
      (diff >= 0 ? "+" : "") +
      pct +
      "%</span>" +
      "</div>" +
      '<div style="font-size:10px;color:var(--text-muted);">' +
      (p.type || "") +
      "</div>" +
      '<div style="font-size:11px;margin:4px 0;">' +
      "买入价: " +
      buyP.toLocaleString() +
      " | 当前估值: " +
      cur.toLocaleString() +
      "</div>" +
      '<div style="display:flex;gap:3px;margin-top:4px;">' +
      '<button class="btn btn-sm btn-danger sell-prop" data-id="' +
      p.id +
      '">出售</button>' +
      "</div>" +
      '<div style="margin-top:4px;height:6px;background:rgba(0,0,0,0.1);border-radius:3px;overflow:hidden;">' +
      '<div style="height:100%;width:' +
      Math.min(100, Math.max(0, (cur / buyP) * 100)) +
      "%;background:" +
      clr +
      ';border-radius:3px;"></div>' +
      "</div>";
    div.appendChild(card);
  }

  area.appendChild(div);

  setTimeout(function () {
    area.querySelectorAll(".sell-prop").forEach(function (b) {
      b.onclick = function () {
        sellProperty(this.dataset.id);
        renderInvestmentTab(state, parent);
      };
    });
  }, 0);
}

// ---- 子tab渲染：汽车 ----
function renderCars(area, inv) {
  var list = inv.cars || [];
  if (list.length === 0) {
    area.innerHTML =
      '<p style="color:var(--text-muted);font-size:12px;">尚未购车，前往商城购买。</p>';
    return;
  }

  var div = document.createElement("div");
  div.className = "action-cards";

  for (var i = 0; i < list.length; i++) {
    var c = list[i];
    var cur = c.currentPrice || c.buyPrice;
    var buyP = c.buyPrice;
    var diff = cur - buyP;
    var pct = ((diff / buyP) * 100).toFixed(1);
    var clr = diff >= 0 ? "var(--success)" : "var(--danger)";

    var card = document.createElement("div");
    card.className = "action-card";
    card.style.borderLeft = "3px solid " + clr;
    card.innerHTML =
      '<div style="display:flex;justify-content:space-between;">' +
      "<strong>" +
      c.name +
      "</strong>" +
      '<span style="color:' +
      clr +
      '">' +
      (diff >= 0 ? "+" : "") +
      pct +
      "%</span>" +
      "</div>" +
      '<div style="font-size:11px;margin:4px 0;">' +
      "买入价: " +
      buyP.toLocaleString() +
      " | 当前估值: " +
      cur.toLocaleString() +
      " | 月维护费: " +
      (c.maintenance || 0) +
      "</div>" +
      '<div style="margin-top:4px;height:6px;background:rgba(0,0,0,0.1);border-radius:3px;overflow:hidden;">' +
      '<div style="height:100%;width:' +
      Math.min(100, Math.max(0, (cur / buyP) * 100)) +
      "%;background:" +
      clr +
      ';border-radius:3px;"></div>' +
      "</div>";
    div.appendChild(card);
  }

  area.appendChild(div);
}

