204	// ====== 状态管理器 ======
205	class GameStateManager {
206	  constructor() {
207	    this._state = null;
208	    this._dirtyFlags = new Set();
209	    this._listeners = [];
210	  }
211	
212	  /** 初始化新游戏 */
213	  newGame() {
214	    this._state = createDefaultState();
215	    this._markAllDirty();
216	    this._notify();
217	    return this._state;
218	  }
219	
220	  /** 获取当前完整状态（只读引用，请勿直接修改嵌套对象） */
221	  getState() {
222	    if (!this._state) {
223	      throw new Error(
224	        "GameState not initialized. Call newGame() or loadGame() first.",
225	      );
226	    }
227	    return this._state;
228	  }
229	
230	  /** 获取状态某个路径的值 */
231	  get(path) {
232	    const parts = path.split(".");
233	    let val = this.getState();
234	    for (const p of parts) {
235	      if (val == null) return undefined;
236	      val = val[p];
237	    }
238	    return val;
239	  }
240	
241	  /**
242	   * 更新状态某个路径的值
243	   * 用法: update('player.age', 25) 或 update('player', { age: 25, ... })
244	   */
245	  update(path, value) {
246	    const parts = path.split(".");
247	    const state = this.getState();
248	
249	    // 导航到父对象
250	    let parent = state;
251	    for (let i = 0; i < parts.length - 1; i++) {
252	      parent = parent[parts[i]];
253	    }
254	
255	    const key = parts[parts.length - 1];
256	    parent[key] = value;
257	
258	    // 标记脏路径
259	    this._dirtyFlags.add(path);
260	    this._notify();
261	  }
262	
263	  /** 批量更新（用于一次性修改多个字段） */
264	  batchUpdate(updates) {
265	    for (const [path, value] of Object.entries(updates)) {
266	      const parts = path.split(".");
267	      const state = this.getState();
268	      let parent = state;
269	      for (let i = 0; i < parts.length - 1; i++) {
270	        parent = parent[parts[i]];
271	      }
272	      parent[parts[parts.length - 1]] = value;
273	      this._dirtyFlags.add(path);
274	    }
275	    this._notify();
276	  }
277	
278	  /** 添加消息到日志 */
279	  addMessage(text, type = "info") {
280	    const state = this.getState();
281	    state.messageLog.push({
282	      day: state.player.day,
283	      text,
284	      type, // 'info'|'success'|'danger'|'event'|'warning'
285	    });
286	    // 限制日志长度
287	    if (state.messageLog.length > 500) {
288	      state.messageLog = state.messageLog.slice(-300);
289	    }
290	    this._dirtyFlags.add("messageLog");
291	    this._notify();
292	  }
293	
294	  /** 导入存档 */
295	  importState(savedState) {
296	    this._state = savedState;
297	    this._state.lastPlayedAt = Date.now();
298	    this._markAllDirty();
299	    this._notify();
300	  }
301	
302	  /** 检查路径是否脏（自上次 cleanDirty 后） */
303	  isDirty(path) {
304	    return this._dirtyFlags.has(path);
305	  }
306	
307	  /** 清除所有脏标记（渲染后调用） */
308	  cleanAllDirty() {
309	    this._dirtyFlags.clear();
310	  }
311	
312	  /** 订阅状态变更 */
313	  onChange(callback) {
314	    this._listeners.push(callback);
315	  }
316	
317	  // ====== 内部方法 ======
318	  _markAllDirty() {
319	    this._dirtyFlags.add("*");
320	  }
321	
322	  _notify() {
323	    for (const cb of this._listeners) {
324	      try {
325	        cb(this._state);
326	      } catch (e) {
327	        /* 静默 */
328	      }
329	    }
330	  }
331	}
332	
333	// ====== 单例导出 ======
334	const StateManager = new GameStateManager();
335	
336	// 使其在全局可访问（方便调试）
337	if (typeof window !== "undefined") {
338	  window.StateManager = StateManager;
339	}
