260	function initInvestment(state) {
261	  var inv = state.investment;
262	  if (!inv) return;
263	  var initialized = false;
264	  for (var i = 0; i < INV_STOCKS.length; i++) {
265	    var s = INV_STOCKS[i];
266	    if (!inv.stockMarket[s.symbol]) {
267	      initialized = true;
268	      var mPrice = s.basePrice * (0.85 + Math.random() * 0.3);
269	      var history = [];
270	      // 回溯生成 5-8 个历史数据点，保证首日就有小曲线
271	      var seedPrice = mPrice * (0.9 + Math.random() * 0.2);
272	      var numPoints = 5 + Math.floor(Math.random() * 4);
273	      for (var k = 0; k < numPoints; k++) {
274	        seedPrice = seedPrice * (1 + s.trend + (Math.random() - 0.5) * 2 * s.volatility);
275	        seedPrice = Math.max(0.5, seedPrice);
276	        history.push({
277	          day: state.player.day - numPoints + k,
278	          price: Math.round(seedPrice * 100) / 100,
279	        });
280	      }
281	      history.push({ day: state.player.day, price: Math.round(mPrice * 100) / 100 });
282	      inv.stockMarket[s.symbol] = {
283	        price: Math.round(mPrice * 100) / 100,
284	        history: history,
285	      };
286	    }
287	  }
288	  if (inv.btcPrice <= 0) inv.btcPrice = 200000;
289	  if (!inv.btcHistory) inv.btcHistory = [];
290	  // 同样为 BTC 生成回溯历史
291	  if (inv.btcHistory.length === 0 && inv.btcPrice > 0) {
292	    var btcSeed = inv.btcPrice * (0.85 + Math.random() * 0.3);
293	    var btcPoints = 5 + Math.floor(Math.random() * 4);
294	    for (var b = 0; b < btcPoints; b++) {
295	      btcSeed = btcSeed * (1 + (Math.random() - 0.5) * 0.08);
296	      btcSeed = Math.max(1000, btcSeed);
297	      inv.btcHistory.push({
298	        day: state.player.day - btcPoints + b,
299	        price: Math.round(btcSeed),
300	      });
301	    }
302	    inv.btcHistory.push({ day: state.player.day, price: inv.btcPrice });
303	    if (inv.btcHistory.length > 30) inv.btcHistory.shift();
304	  }
305	  inv.lastTickDay = state.player.day;
306	}
307	
308	function tickInvestmentDaily(state) {
309	  var inv = state.investment;
310	  if (!inv || inv.lastTickDay >= state.player.day) return;
311	  inv.lastTickDay = state.player.day;
312	
313	  // 股票/贵金属/期货/基金每日波动
314	  for (var i = 0; i < INV_STOCKS.length; i++) {
315	    var s = INV_STOCKS[i];
316	    var m = inv.stockMarket[s.symbol];
317	    if (!m) continue;
318	    m.price = Math.max(
319	      0.01,
320	      m.price * (1 + s.trend + (Math.random() - 0.5) * 2 * s.volatility),
321	    );
322	    m.price = Math.round(m.price * 100) / 100;
323	    m.history.push({ day: state.player.day, price: m.price });
324	    if (m.history.length > 20) m.history.shift();
325	  }
326	
327	  // 比特币
328	  if (inv.btcPrice > 0) {
329	    inv.btcFearGreed = Math.max(
330	      5,
331	      Math.min(95, (inv.btcFearGreed || 50) + (Math.random() - 0.5) * 10),
332	    );
333	    inv.btcPrice = Math.max(
334	      1000,
335	      Math.round(
336	        inv.btcPrice *
337	          (1 +
338	            (Math.random() - 0.5) * 0.08 +
339	            ((inv.btcFearGreed - 50) / 50) * 0.02),
340	      ),
341	    );
342	    if (!inv.btcHistory) inv.btcHistory = [];
343	    inv.btcHistory.push({ day: state.player.day, price: inv.btcPrice });
344	    if (inv.btcHistory.length > 30) inv.btcHistory.shift();
345	
346	    if (state.player.day - inv.btcHalvingDay > 1460) {
347	      inv.btcHalvingDay = state.player.day;
348	      inv.btcFearGreed = Math.min(95, inv.btcFearGreed + 20);
349	      StateManager.addMessage("比特币减半事件！", "event");
350	    }
351	  }
352	
353	  // 房产
354	  for (var p = 0; p < (inv.properties || []).length; p++) {
355	    var prop = inv.properties[p];
356	    prop.currentPrice = Math.round(
357	      (prop.currentPrice || prop.buyPrice) *
358	        (1 + prop.appreciation + (Math.random() - 0.5) * 0.002),
359	    );
360	    if (state.player.day % 30 === 0) state.resources.cash += prop.rent || 0;
361	  }
362	
363	  // 汽车
364	  for (var c = 0; c < (inv.cars || []).length; c++) {
365	    var car = inv.cars[c];
366	    car.currentPrice = Math.round(
367	      (car.currentPrice || car.buyPrice) * (1 - car.depreciation),
368	    );
369	    if (state.player.day % 30 === 0 && state.resources.cash >= car.maintenance)
370	      state.resources.cash -= car.maintenance;
371	  }
372	}
