374	function buyInvStock(symbol, shares) {
375	  var state = StateManager.getState();
376	  var inv = state.investment;
377	  var m = inv.stockMarket[symbol];
378	  if (!m) return;
379	  var cost = Math.round(m.price * shares * 100) / 100;
380	  if (state.resources.cash < cost) {
381	    StateManager.addMessage("现金不足", "danger");
382	    return;
383	  }
384	  state.resources.cash -= cost;
385	  var h = inv.stockHoldings.find(function (s) {
386	    return s.symbol === symbol;
387	  });
388	  if (h) {
389	    var total = h.shares + shares;
390	    h.avgPrice =
391	      Math.round(((h.avgPrice * h.shares + cost) / total) * 100) / 100;
392	    h.shares = total;
393	  } else
394	    inv.stockHoldings.push({
395	      symbol: symbol,
396	      shares: shares,
397	      avgPrice: m.price,
398	    });
399	  StateManager.addMessage("买入 " + symbol + " " + shares + "股", "success");
400	}
