402	function sellInvStock(symbol, shares) {
403	  var state = StateManager.getState();
404	  var inv = state.investment;
405	  var h = inv.stockHoldings.find(function (s) {
406	    return s.symbol === symbol;
407	  });
408	  if (!h || h.shares < shares) {
409	    StateManager.addMessage("持仓不足", "danger");
410	    return;
411	  }
412	  var m = inv.stockMarket[symbol];
413	  var revenue = Math.round(m.price * shares * 100) / 100;
414	  state.resources.cash += revenue;
415	  h.shares -= shares;
416	  if (h.shares <= 0)
417	    inv.stockHoldings = inv.stockHoldings.filter(function (s) {
418	      return s.symbol !== symbol;
419	    });
420	  StateManager.addMessage("卖出 " + symbol + " " + shares + "股", "success");
421	}
