427	  if (state.resources.cash < cost) {
428	    StateManager.addMessage("现金不足", "danger");
429	    return;
430	  }
431	  state.resources.cash -= cost;
432	  inv.btcHoldings = Math.round((inv.btcHoldings + amount) * 10000) / 10000;
433	  StateManager.addMessage("买入 " + amount + " BTC", "success");
434	}
