440	    StateManager.addMessage("持仓不足", "danger");
441	    return;
442	  }
443	  state.resources.cash += Math.round(inv.btcPrice * amount * 100) / 100;
444	  inv.btcHoldings = Math.round((inv.btcHoldings - amount) * 10000) / 10000;
445	  StateManager.addMessage("卖出 " + amount + " BTC", "success");
446	}
