448	function buyProperty(propId) {
449	  var state = StateManager.getState();
450	  var inv = state.investment;
451	  var prop = PROPERTIES.find(function (p) {
452	    return p.id === propId;
453	  });
454	  if (!prop) return;
455	  if (state.resources.cash < prop.price) {
456	    StateManager.addMessage("现金不足", "danger");
457	    return;
458	  }
459	  state.resources.cash -= prop.price;
460	  inv.properties.push({
461	    id: prop.id,
462	    name: prop.name,
463	    type: prop.type,
464	    appreciation: prop.appreciation,
465	    rent: prop.rent,
466	    buyPrice: prop.price,
467	    currentPrice: prop.price,
468	    buyDay: state.player.day,
469	  });
470	  StateManager.addMessage("购入" + prop.name, "success");
471	}
