473	function sellProperty(propId) {
474	  var state = StateManager.getState();
475	  var inv = state.investment;
476	  var idx = -1;
477	  for (var i = 0; i < inv.properties.length; i++) {
478	    if (inv.properties[i].id === propId) {
479	      idx = i;
480	      break;
481	    }
482	  }
483	  if (idx < 0) return;
484	  var prop = inv.properties[idx];
485	  var net = prop.currentPrice - Math.round(prop.currentPrice * 0.05);
486	  state.resources.cash += net;
487	  inv.properties.splice(idx, 1);
488	  StateManager.addMessage("出售" + prop.name + " 到手" + net, "success");
489	}
