503	  inv.cars.push({
504	    id: car.id,
505	    name: car.name,
506	    depreciation: car.depreciation,
507	    maintenance: car.maintenance,
508	    travelBonus: car.travelBonus,
509	    buyPrice: car.price,
510	    currentPrice: car.price,
511	    buyDay: state.player.day,
512	  });
