    "waste_recycling",
    "manual_labor_construction",
    "warehouse_worker",
    "factory_work_assembly",
  ];
  if (boostedJobs.includes(job.id)) {
    const newbieBonus = job.id === "waste_recycling" ? 3 : 3;
    pay += newbieBonus;
